      urlTooltip.style.top = top + &#39;px&#39;;
      urlTooltip.style.left = left + &#39;px&#39;;

    } else {
      urlTooltip.style.display = &#39;none&#39;;
      mainImage.style.cursor = &#39;default&#39;;
