  } else {
    // Mouse does not point to any boxed area
    // But if we&#39;re hovering a label, don&#39;t reset the hover image
    // (The label&#39;s mouseleave will handle that)
    if (hoveringChildId !== null) {
      const labelEl = document.getElementById(`label-${hoveringChildId}`);
      if (!labelEl || !labelEl.matches(&#39;:hover&#39;)) {
        if (hoveringChildId !== pinnedChildId) {
          highlightLabel(hoveringChildId, false);
        }
        if (pinnedChildId) {
          showHoverOverlay(pinnedChildId);
        } else {
          hideHoverOverlay();
        }
        hoveringChildId = null;
      }
    }
    // Hide the tooltip
    urlTooltip.style.display = &#39;none&#39;;
    mainImage.style.cursor = &#39;default&#39;;
  }
});

// Mouse Leave: cancel the hover status if mouse leaves the main container.
mainContainer.addEventListener(&#39;mouseleave&#39;, () =&gt; {
  if (isAnimating) return;
  if (hoveringChildId !== null) {
    if (hoveringChildId !== pinnedChildId) {
      highlightLabel(hoveringChildId, false);
    }
    if (pinnedChildId) {
      showHoverOverlay(pinnedChildId);
    } else {
      hideHoverOverlay();
